async function manager(section){const version=state.routeVersion;const [m,w]=await Promise.all([api('/api/manager'),api('/api/workspace')]);if(!routeIsCurrent(version))return;state.manager=m;state.workspace=w;const tasks=m.tasks||[];page(({overview:'总览',projects:'项目',tasks:'任务',production:'生产流程',team:'团队'})[section]||'管理工作区','MANAGER WORKSPACE');let html='';if(section==='overview'){const a=w.ai_usage||{};html=`<div class="welcome"><div><span class="eyebrow">OPERATIONS</span><h2>正在发生的工作</h2><p>只统计真实登记的任务、审核与调用。</p></div></div><div class="stats">${stat('实际任务',tasks.length)}${stat('待复核',w.needs_review)}${stat('待处理升级',w.open_escalations)}${stat('AI 调用',a.calls||0)}</div><div class="stats">${stat('制作中',tasks.filter(t=>t.status==='in_progress').length)}${stat('待 QC',tasks.filter(t=>['technical_checked','ai_prechecked','human_review'].includes(t.status)).length)}${stat('返修',tasks.filter(t=>t.status==='revision_required').length)}${stat('阻塞',tasks.filter(t=>t.status==='blocked').length)}</div><div class="section-title"><h2>需要关注</h2></div>${w.escalations?.length?`<div class="task-list">${w.escalations.map(e=>`<button class="task-row" data-task="${esc(e.task_id)}"><span class="task-core"><strong>${esc(e.title)}</strong><small>${esc(e.reason)}</small></span><span class="arrow">→</span></button>`).join('')}</div>`:'<div class="empty compact">目前没有升级处理事项</div>'}<div class="section-title"><h2>近期任务</h2></div><div class="task-list">${tasks.slice(0,15).map(taskRow).join('')}</div>`}else if(section==='projects'){html=`<div class="project-grid">${w.projects.map(p=>`<button class="project-card" data-view="project:${esc(p.id)}"><span class="eyebrow">PROJECT</span><h2>${esc(p.name)}</h2><p>实际任务 ${Object.values(p.counts).reduce((a,b)=>a+b,0)} · 素材 ${p.asset_count}</p><small>规划总量未登记</small><span>查看项目 →</span></button>`).join('')}</div>`}else if(section==='tasks'){
  const table=items=>`<div class="object-list"><div class="object-list-toolbar"><input data-object-search placeholder="搜索任务、项目或负责人" aria-label="搜索任务"><small>共 ${items.length} 项</small></div><div class="object-list-scroll"><table><thead><tr><th>任务</th><th>项目</th><th>负责人</th><th>状态</th><th>优先级</th><th>操作</th></tr></thead><tbody>${items.map(task=>`<tr data-object-row data-search="${esc([task.title,projectName[task.project_id]||task.project_id,m.users.find(u=>u.id===task.assignee_id)?.display_name||'',statusName[task.status]||task.status].join(' '))}"><td><button data-task="${esc(task.id)}"><strong>${esc(task.title)}</strong></button><small>${esc(task.workflow_id)}</small></td><td>${esc(projectName[task.project_id]||task.project_id)}</td><td>${esc(m.users.find(u=>u.id===task.assignee_id)?.display_name||'待分派')}</td><td>${badge(task.status)}</td><td>${esc(task.priority)}</td><td><button data-task="${esc(task.id)}">查看详情 →</button></td></tr>`).join('')||'<tr><td colspan="6" class="object-list-empty">当前没有任务</td></tr>'}</tbody></table></div></div>`;
  const pending=tasks.filter(t=>['blocked','revision_required','technical_checked','ai_prechecked','human_review'].includes(t.status)),working=tasks.filter(t=>['assigned','in_progress','submitted'].includes(t.status)),done=tasks.filter(t=>t.status==='accepted');
  html=`<div class="section-title"><h2>全部任务</h2><div class="actions"><button class="outline" data-panel="create">新建任务</button><button class="outline" data-panel="asset">登记素材</button></div></div><div id="create-panels"></div>${objectTabs('manager-tasks',[['pending',`待处理 · ${pending.length}`,table(pending)],['working',`进行中 · ${working.length}`,table(working)],['done',`已完成 · ${done.length}`,table(done)],['all',`全部 · ${tasks.length}`,table(tasks)]],'pending')}`;
}else if(section==='production'){const a=w.ai_usage||{};html=`<div class="stats">${stat('AI 调用',a.calls||0)}${stat('输入 token',a.input_tokens||0)}${stat('输出 token',a.output_tokens||0)}${stat('已记录费用',a.known_cost==null?'未知':'¥'+Number(a.known_cost).toFixed(3),a.priced_calls<a.calls?'部分调用费用未返回':'')}</div><div class="stats">${stat('AI 准备',w.ai_kinds?.prepare||0)}${stat('AI 初检',w.ai_kinds?.precheck||0)}${stat('任务助手',w.ai_kinds?.copilot||0)}${stat('媒体任务','未知','由创作中心记录')}</div><div class="section-title"><h2>生产阶段</h2></div><div class="stage-grid">${['planned','ready','assigned','in_progress','submitted','technical_checked','ai_prechecked','human_review','revision_required','accepted'].map(s=>`<div class="stage"><span>${esc(statusName[s])}</span><strong>${tasks.filter(t=>t.status===s).length}</strong></div>`).join('')}</div><div class="section-title"><h2>待复核任务</h2></div><div class="task-list">${tasks.filter(t=>['technical_checked','ai_prechecked','human_review'].includes(t.status)).map(taskRow).join('')||'<div class="empty compact">暂无待复核任务</div>'}</div>`}else{
  const users=m.users.filter(u=>u.active),table=items=>`<div class="object-list"><div class="object-list-toolbar"><input data-object-search placeholder="搜索姓名或账号" aria-label="搜索团队成员"><small>共 ${items.length} 人</small></div><div class="object-list-scroll"><table><thead><tr><th>姓名</th><th>账号</th><th>角色</th><th>生产岗位</th></tr></thead><tbody>${items.map(u=>`<tr data-object-row data-search="${esc([u.display_name,u.username,roles[u.role],u.martial_specialist?'武术生产':''].join(' '))}"><td><strong>${esc(u.display_name)}</strong></td><td>${esc(u.username)}</td><td>${esc(roles[u.role]||u.role)}</td><td>${u.martial_specialist?'武术生产':'—'}</td></tr>`).join('')||'<tr><td colspan="4" class="object-list-empty">当前没有成员</td></tr>'}</tbody></table></div></div>`;
  html=`<div class="section-title"><h2>团队成员</h2><button class="outline" data-panel="user">新增员工</button></div><div id="create-panels"></div>${objectTabs('manager-team',[['all',`全部 · ${users.length}`,table(users)],['employees',`员工 · ${users.filter(u=>u.role==='employee').length}`,table(users.filter(u=>u.role==='employee'))],['managers',`管理者 · ${users.filter(u=>u.role!=='employee').length}`,table(users.filter(u=>u.role!=='employee'))]],'all')}`;
}$('#content').innerHTML=html}
async function founder(){const [d,w]=await Promise.all([api('/api/founder'),api('/api/workspace')]);page('需要我决定','FOUNDER WORKSPACE');$('#content').innerHTML=`<div class="welcome"><div><span class="eyebrow">FOUNDER</span><h2>关键决定在这里</h2><p>定版、关键验收与跨项目判断保持人工责任。</p></div></div><div class="stats">${stat('待我验收',d.needs_my_decision.length)}${stat('升级事项',w.open_escalations)}${stat('实际项目',d.project_snapshot.length)}</div><div class="section-title"><h2>等待关键验收</h2></div>${d.needs_my_decision.length?`<div class="task-list">${d.needs_my_decision.map(taskRow).join('')}</div>`:'<div class="empty compact">目前没有必须由你验收的作品</div>'}<div class="section-title"><h2>项目快照</h2></div><div class="project-grid">${d.project_snapshot.map(p=>`<button class="project-card" data-view="project:${esc(p.id)}"><h2>${esc(p.name)}</h2><p>实际任务 ${Object.values(p.counts).reduce((a,b)=>a+b,0)}</p><span>查看项目 →</span></button>`).join('')}</div>`}
function panel(which){const root=$('#create-panels');if(!root)return;let html='';if(which==='user')html=`<div class="card"><h3>新增员工</h3><form id="user-form" class="form-grid"><label>登录账号<input name="username" required></label><label>员工姓名<input name="display_name" required></label><label class="full">初始密码（至少12位）<input name="password" type="password" minlength="12" required></label><button class="primary">创建账号</button></form></div>`;if(which==='asset')html=`<div class="card"><h3>登记现有素材</h3><form id="asset-form" class="form-grid"><label>项目<select name="project_id"><option value="wuxiang">万象武境</option><option value="diaojianghu">钓江湖</option></select></label><label>素材类型<select name="type">${Object.entries(assetName).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="full">显示名称<input name="name" required></label><label class="full">现有文件路径、HTTPS 或 studio://素材编号<input name="storage_ref" required></label><label class="full">远程素材 SHA-256（本机文件留空）<input name="sha256" pattern="[a-f0-9]{64}"></label><button class="primary">登记素材引用</button></form></div>`;if(which==='create')html=`<div class="card"><h3>新建业务任务</h3><p class="muted">先登记真实素材；功法任务需锁定角色与真人动作参考。</p><form id="create-form" class="form-grid"><label>项目<select name="project_id" id="new-project"><option value="wuxiang">万象武境</option><option value="diaojianghu">钓江湖</option></select></label><label>流程<select name="workflow_id" id="new-workflow"><option value="WF-01">功法教学资产</option><option value="WF-02">创意短视频</option><option value="WF-03">内容与运营</option></select></label><label class="full">员工要做什么<input name="title" required></label><label class="full">为什么做<textarea name="why" required></textarea></label><label class="full">当前事实与目标<textarea name="context"></textarea></label><label class="full">操作步骤（每行一步）<textarea name="instructions"></textarea></label><label class="full">输入素材编号（逗号分隔）<input name="input_assets"></label><div id="locks" class="full form-grid"><label>定版角色素材编号<input name="character_asset_id"></label><label>角色身份<input name="identity"></label><label>角色禁止变化项<textarea name="forbidden_changes"></textarea></label><label>真人动作参考素材编号<input name="motion_asset_id"></label><label>招式名称<input name="move"></label><label>参考起点秒<input name="start" type="number" step="0.01" value="0"></label><label>参考终点秒<input name="end" type="number" step="0.01"></label><label>画面方向<input name="orientation"></label><label class="full">关键动作时刻<textarea name="key_moments"></textarea></label></div><label>费用上限 ¥<input name="budget_cap" type="number" min="0" max="100" step="0.01" value="0"></label><label>创始人最终验收<select name="founder_required"><option value="0">不需要</option><option value="1">需要</option></select></label><button class="primary">创建待准备任务</button></form></div>`;root.innerHTML=html;if(which==='create'){const change=()=>{$('#locks').classList.toggle('hidden',$('#new-workflow').value!=='WF-01');if($('#new-project').value==='diaojianghu')$('#new-workflow').value='WF-03'};$('#new-workflow').onchange=change;$('#new-project').onchange=change;change()}}
async function upload(file){if(!file)return null;if(file.size>50_000_000)throw new Error('文件超过 50MB，请先在原工具归档并填写链接或编号');const raw=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('读取文件失败'));reader.readAsDataURL(file)});return {name:file.name,base64:raw.split(',')[1]}}
function fields(form){return Object.fromEntries(new FormData(form).entries())}
async function runAction(b){const action=b.dataset.action,d=state.task;if(action==='copy-prompt'){await navigator.clipboard.writeText(d.ai_prepared?.generation_prompt||'');notice('制作说明已复制');return}if(action==='view-text'){const box=$('#asset-text-'+b.dataset.asset);if(!box)return;if(!box.textContent){const result=await api('/api/assets/'+encodeURIComponent(b.dataset.asset)+'/text');box.textContent=result.text}box.classList.toggle('hidden');b.textContent=box.classList.contains('hidden')?'展开原文':'收起原文';return}if(action==='open-asset'){const a=await api('/api/assets/'+encodeURIComponent(b.dataset.asset));window.open(a.external_url||'https://ai.duodianqian.cn/','_blank','noopener');return}if(action==='start'){await api(`/api/tasks/${d.id}/start`,{});notice('任务已开始');return taskDetail(d.id)}if(action==='choose'){const reason=prompt('为什么选用这个版本？请写明主要理由。');if(!reason)return;await api(`/api/tasks/${d.id}/choose-candidate`,{candidate_id:b.dataset.candidate,reason});notice('已选用候选作品');return taskDetail(d.id)}if(action==='assign'){const employee_id=$('#assign-user')?.value;if(!employee_id)throw new Error('请选择员工');await api(`/api/tasks/${d.id}/assign`,{employee_id});notice('任务已分派');return taskDetail(d.id)}if(['prepare','sync-prepare','precheck','sync-precheck'].includes(action)){const r=await api(`/api/tasks/${d.id}/${action}`,{});notice(r.status==='running'||r.status==='queued'?'已进入后台处理；稍后手动读取结果':r.status==='failed'?'执行未完成，请查看记录':'执行状态已保存',r.status==='failed');return taskDetail(d.id)}if(action==='skip-precheck'){const reason=prompt('请说明 AI 初检无法完成的原因；此项将保留为未核实。');if(!reason)return;await api(`/api/tasks/${d.id}/skip-precheck`,{reason});return taskDetail(d.id)}}
document.addEventListener('click',async e=>{const objectTab=e.target.closest('[data-object-tab]');if(objectTab){selectObjectTab(objectTab.closest('[data-object-tabs]'),objectTab.dataset.objectTab);return}const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;return taskDetail(state.task.id)}const ai=e.target.closest('[data-open-ai-project]');if(ai){window.aiStudio?.setContext(ai.dataset.openAiProject,ai.dataset.openAiTask||'');return go('ai:assistant')}const nav=e.target.closest('[data-view]');if(nav)return go(nav.dataset.view);const row=e.target.closest('[data-task]');if(row)return go('task:'+row.dataset.task);const quick=e.target.closest('[data-quick]');if(quick){const f=$('#ask-form');if(f){f.elements.question.value=quick.dataset.quick;f.elements.category.value=quick.dataset.category;f.elements.question.focus()}return}const pan=e.target.closest('[data-panel]');if(pan)return panel(pan.dataset.panel);const btn=e.target.closest('[data-action]');if(!btn||btn.disabled)return;try{btn.disabled=true;btn.setAttribute('aria-busy','true');btn.classList.add('is-busy');await runAction(btn)}catch(err){notice(err.message,true)}finally{btn.disabled=false;btn.removeAttribute('aria-busy');btn.classList.remove('is-busy')}});
document.addEventListener('change',e=>{if(!['works-project','works-type','works-date'].includes(e.target.id))return;workState.filter={project:$('#works-project')?.value||'',type:$('#works-type')?.value||'',date:$('#works-date')?.value||''};renderWorks()});
document.addEventListener('input',e=>{const search=e.target.closest?.('[data-object-search]');if(!search)return;const q=search.value.trim().toLocaleLowerCase('zh-CN');search.closest('.object-list')?.querySelectorAll('[data-object-row]').forEach(row=>{row.hidden=!String(row.dataset.search||row.textContent).toLocaleLowerCase('zh-CN').includes(q)})});
document.addEventListener('submit',async e=>{const f=e.target;if(!['login-form','candidate-form','selected-form','ask-form','review-form','user-form','asset-form','create-form'].includes(f.id)&&!f.classList.contains('escalation-form'))return;e.preventDefault();const button=f.querySelector('button[type=submit],button:not([type])');if(button){button.disabled=true;button.setAttribute('aria-busy','true');button.classList.add('is-busy')}try{const d=fields(f);if(f.id==='login-form'){const r=await api('/api/login',d);state.user=r.user;state.csrf=r.csrf;state.scrollPositions.clear();state.objectTabs.clear();shell();go((state.user.martial_specialist?'martial:today':state.user.role==='employee'?'today':state.user.role==='founder'?'founder':'manager:overview'),'replace');return}if(f.id==='candidate-form'){const file=f.querySelector('input[type=file]').files[0];let asset_id=null;if(file){const uploadData=await upload(file);const result=await api(`/api/tasks/${state.task.id}/upload-candidate`,{upload:uploadData});asset_id=result.asset.id}await api(`/api/tasks/${state.task.id}/candidate`,{...d,asset_id,external_url:d.external_url||null,provider_job_id:d.provider_job_id||null});notice('候选已留存');return taskDetail(state.task.id)}if(f.id==='selected-form'){await api(`/api/tasks/${state.task.id}/submit-selected`,d);notice('作品已提交，技术检查已记录');return taskDetail(state.task.id)}if(f.id==='ask-form'){await api(`/api/tasks/${state.task.id}/ask`,d);notice('问题已提交');return taskDetail(state.task.id)}if(f.classList.contains('escalation-form')){await api(`/api/tasks/${state.task.id}/resolve-escalation`,{escalation_id:f.dataset.escalation,resolution:d.resolution});notice('已记录管理者处理结论');return taskDetail(state.task.id)}if(f.id==='review-form'){await api(`/api/tasks/${state.task.id}/${f.dataset.kind}-review`,{...d,evidence_refs:(d.evidence_refs||'').split('\n').filter(Boolean)});notice('复核结论已保存');return taskDetail(state.task.id)}if(f.id==='user-form'){await api('/api/users',{...d,role:'employee'});notice('员工账号已创建');return manager('team')}if(f.id==='asset-form'){const a=await api('/api/assets',d);notice(`素材已登记：${a.id}`);return manager('tasks')}if(f.id==='create-form'){const lines=x=>String(x||'').split('\n').map(s=>s.trim()).filter(Boolean);const assets=(d.input_assets||'').split(',').map(x=>x.trim()).filter(Boolean);const spec={project_id:d.project_id,workflow_id:d.workflow_id,title:d.title,why:d.why,context:{summary:d.context},instructions:lines(d.instructions),input_assets:assets,budget_cap:Number(d.budget_cap||0),founder_required:d.founder_required==='1',deliverable_contract:{required:'文件或结果链接或平台任务编号'},qc_contract:{criteria:[]}};if(d.workflow_id==='WF-01'){for(const id of [d.character_asset_id,d.motion_asset_id])if(!assets.includes(id))assets.push(id);spec.character_lock={asset_id:d.character_asset_id,identity:d.identity,version:1,forbidden_changes:lines(d.forbidden_changes)};spec.motion_lock={asset_id:d.motion_asset_id,move:d.move,start:Number(d.start),end:Number(d.end),orientation:d.orientation,key_moments:lines(d.key_moments),version:1}}const t=await api('/api/tasks',spec);notice('任务已创建，请先完成 AI 准备');return go('task:'+t.id)}}catch(err){if(f.id==='login-form')$('#login-error').textContent=err.message;else notice(err.message,true)}finally{if(button){button.disabled=false;button.removeAttribute('aria-busy');button.classList.remove('is-busy')}}});
$('#logout').addEventListener('click',async()=>{try{await api('/api/logout',{})}catch{}state.user=null;state.csrf='';state.scrollPositions.clear();state.objectTabs.clear();showLogin()});
(async()=>{try{const r=await api('/api/me');state.user=r.user;state.csrf=r.csrf;state.scrollPositions.clear();state.objectTabs.clear();shell();go(routeFromLocation()||(state.user.martial_specialist?'martial:today':state.user.role==='employee'?'today':state.user.role==='founder'?'founder':'manager:overview'),'replace')}catch{showLogin()}})();
